@Override
    public boolean hurt(DamageSource source, float damage) {
        boolean flag = super.hurt(source, damage);
        boolean isSpitting = getAnimation() == SPIT_ANIMATION && getAnimationTick() < 30;
        boolean isSwooping = getAnimation() == SWOOP_ANIMATION && getAnimationTick() < 25;
        if (flag && movement != EnumNagaMovement.FALLING && (isSpitting || isSwooping) && damage > 0) {
            AnimationHandler.INSTANCE.sendAnimationMessage(this, EntityNaga.HURT_TO_FALL_ANIMATION);
            interrupted = true;
        }
        return flag;
    }

@Override
    public void tick() {
        prevMotionX = getDeltaMovement().x;
        prevMotionY = getDeltaMovement().y;
        prevMotionZ = getDeltaMovement().z;
        prevHoverAnimFrac = hoverAnimFrac;
        prevFlapAnimFrac = flapAnimFrac;

        super.tick();
//        setDead();
        yBodyRot = getYRot();
        if (level().isClientSide()) {
            banking = getBanking();
            prevBanking = getPrevBanking();
        }

        if (spitCooldown > 0) spitCooldown--;
        if (swoopCooldown > 0) swoopCooldown--;
        if (onGroundTimer > 0) onGroundTimer--;
        if (roarAnimation < ROAR_DURATION) roarAnimation++;

        if (getAnimation() == null) AnimationHandler.INSTANCE.sendAnimationMessage(this, NO_ANIMATION);

        if (hasEffect(MobEffects.POISON)) removeEffectNoUpdate(MobEffects.POISON);

//        if (tickCount == 1) {
//            System.out.println("Naga at " + position());
//        }

        if (!level().isClientSide) {
            if (getTarget() != null && targetDistance < 29.5 && movement != EnumNagaMovement.FALLEN && movement != EnumNagaMovement.FALLING) {
                setAttacking(true);
                if (getAnimation() == NO_ANIMATION && swoopCooldown == 0 && random.nextInt(80) == 0 && getY() - getTarget().getY() > 0) {
                    interrupted = false;
//                    System.out.println("Swoop");
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SWOOP_ANIMATION);
                    swoopCooldown = SWOOP_COOLDOWN_MAX;
                }
                else if (getAnimation() == NO_ANIMATION && spitCooldown == 0 && random.nextInt(80) == 0) {
                    interrupted = false;
//                    System.out.println("Spit");
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SPIT_ANIMATION);
                    spitCooldown = SPIT_COOLDOWN_MAX;
                }
            } else {
                setAttacking(false);
            }
        }

        if (movement != EnumNagaMovement.FALLING && movement != EnumNagaMovement.FALLEN) {
            if (getAttacking()) {
                movement = EnumNagaMovement.HOVERING;
                hoverAnim.increaseTimer();

                if (getAnimation() == NO_ANIMATION && !level().isClientSide) {
                    List<Projectile> projectilesNearby = getEntitiesNearby(Projectile.class, 30);
                    for (Projectile a : projectilesNearby) {
                        Vec3 aActualMotion = new Vec3(a.getX() - a.xo, a.getY() - a.yo, a.getZ() - a.zo);
                        if (aActualMotion.length() < 0.1 || a.tickCount <= 1) {
                            continue;
                        }

                        float dot = (float) a.getDeltaMovement().normalize().dot(this.position().subtract(a.position()).normalize());
                        if (dot > 0.96) {
                            Vec3 dodgeVec = a.getDeltaMovement().cross(new Vec3(0, 1, 0)).normalize().scale(1.2);
                            Vec3 newPosLeft = position().add(dodgeVec.scale(2));
                            Vec3 newPosRight = position().add(dodgeVec.scale(-2));
                            Vec3 diffLeft = newPosLeft.subtract(a.position());
                            Vec3 diffRight = newPosRight.subtract(a.position());
                            if (diffRight.dot(a.getDeltaMovement()) > diffLeft.dot(a.getDeltaMovement())) {
                                dodgeVec = dodgeVec.scale(-1);
                            }
                            setDeltaMovement(getDeltaMovement().add(dodgeVec));
                            AnimationHandler.INSTANCE.sendAnimationMessage(this, DODGE_ANIMATION);
                        }
                    }
                }
            }
            else {
                movement = EnumNagaMovement.GLIDING;
                hoverAnim.decreaseTimer();
                flapAnim.decreaseTimer();
            }
        }
        else if (movement == EnumNagaMovement.FALLING) {
            if (onGround() || isInLava() || isInWater()) {
                AnimationHandler.INSTANCE.sendAnimationMessage(this, EntityNaga.LAND_ANIMATION);
                movement = EnumNagaMovement.FALLEN;
                onGroundTimer = GROUND_TIMER_MAX;
                setDeltaMovement(0, getDeltaMovement().y, 0);
                getNavigation().stop();
            }
        }

        if (movement == EnumNagaMovement.FALLEN) {
            if (onGroundTimer <= 0 && getAnimation() == NO_ANIMATION) {
                setAnimationTick(0);
                AnimationHandler.INSTANCE.sendAnimationMessage(this, EntityNaga.GET_UP_ANIMATION);
            }
        }

        if (getAnimation() == SWOOP_ANIMATION && getAnimationTick() < 43) {
            hoverAnim.increaseTimer();
            flapAnim.decreaseTimer();
        }
        else if (getAnimation() == HURT_TO_FALL_ANIMATION) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else if (getAnimation() == LAND_ANIMATION) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else if (getAnimation() == GET_UP_ANIMATION && getAnimationTick() < 26) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else if (movement == EnumNagaMovement.FALLEN) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
            setYRot(yRotO);
            yHeadRot = yHeadRotO;
            setXRot(xRotO);
        }
        else if (movement == EnumNagaMovement.FALLING) {
            flapAnim.decreaseTimer();
            hoverAnim.increaseTimer();
        }
        else {
            flapAnim.increaseTimer();
        }

        if (getAnimation() == SPIT_ANIMATION && level().isClientSide && mouthPos != null && !interrupted) {
            if (getAnimationTick() == 33) {
//            System.out.println(mouthPos);
                float explodeSpeed = 2.4f;
                for (int i = 0; i < 25; i++) {
                    Vec3 particlePos = new Vec3(0.25, 0, 0);
                    particlePos = particlePos.yRot((float) (random.nextFloat() * 2 * Math.PI));
                    particlePos = particlePos.xRot((float) (random.nextFloat() * 2 * Math.PI));
                    double value = random.nextFloat() * 0.1f;
                    double life = random.nextFloat() * 10f + 20f;
                    ParticleVanillaCloudExtended.spawnVanillaCloud(level(), particlePos.x + mouthPos[0].x, particlePos.y + mouthPos[0].y, particlePos.z + mouthPos[0].z, particlePos.x * explodeSpeed, particlePos.y * explodeSpeed, particlePos.z * explodeSpeed, 1, 0.25d + value, 0.75d + value, 0.25d + value, 0.6, life);
                }
            }

            if (getAnimationTick() <= 15 && mouthPos != null && !interrupted) {
//            System.out.println(mouthPos);

                int howMany = 4;
                for (int i = 0; i < howMany; i++) {
                    Vec3 particlePos = new Vec3(3, 0, 0);
                    particlePos = particlePos.yRot((float) (random.nextFloat() * 2 * Math.PI));
                    particlePos = particlePos.xRot((float) (random.nextFloat() * 2 * Math.PI));
                    double value = random.nextFloat() * 0.15f;
                    ParticleVanillaCloudExtended.spawnVanillaCloudDestination(level(), particlePos.x + mouthPos[0].x, particlePos.y + mouthPos[0].y, particlePos.z + mouthPos[0].z, 0, 0, 0, 1, 0.25d + value, 0.75d + value, 0.25d + value, 0.9, 15, mouthPos);
                }
            }
        }

        if (getAnimation() == HURT_TO_FALL_ANIMATION && getAnimationTick() == 17) {
            movement = EnumNagaMovement.FALLING;
        }

        if (getAnimation() == GET_UP_ANIMATION && getAnimationTick() == 26) {
            movement = EnumNagaMovement.HOVERING;
        }

        if (level().isClientSide && movement == EnumNagaMovement.HOVERING && flapAnim.getAnimationFraction() >= 0.5) {

            if (shoulderRot > 0.9) hasFlapSoundPlayed = false;

            if (shoulderRot <= 0.7 && !hasFlapSoundPlayed) {
                level().playLocalSound(getX(), getY(), getZ(), MMSounds.ENTITY_NAGA_FLAP_1.get(), SoundSource.HOSTILE, 2, (float) (0.85 + random.nextFloat() * 0.2), false);
                hasFlapSoundPlayed = true;
            }
        }

        hoverAnimFrac = hoverAnim.getAnimationProgressSinSqrt();
        flapAnimFrac = flapAnim.getAnimationProgressSinSqrt();

        if (!this.level().isClientSide && this.level().getDifficulty() == Difficulty.PEACEFUL)
        {
            this.discard() ;
        }

//        setAttacking(true);
//        getNavigator().clearPath();
//        setMotion(new Vector3d(0, 0, 0));
//        setPosition(getPosX(), 10, getPosZ());
//
//        if (getAnimation() == NO_ANIMATION) {
//            AnimationHandler.INSTANCE.sendAnimationMessage(this, TAIL_DEMO_ANIMATION);
//        }
    }

@Override
    public void performRangedAttack(LivingEntity target, float distanceFactor) {
        if (interrupted) return;
        Vec3 projectilePos = new Vec3(1, -0.7, 0);
        projectilePos = projectilePos.yRot((float)Math.toRadians(-getYRot() - 90));
        projectilePos = projectilePos.add(position());
        projectilePos = projectilePos.add(new Vec3(0, 0, 1).xRot((float)Math.toRadians(-getXRot())).yRot((float)Math.toRadians(-yHeadRot)));
        projectilePos = projectilePos.add(new Vec3(0, 0, 0));
        EntityPoisonBall poisonBall = new EntityPoisonBall(EntityHandler.POISON_BALL.get(), this.level(), this);
        poisonBall.setPos(projectilePos.x, projectilePos.y, projectilePos.z);
        Vec3 look = getLookAngle();
        Vec3 dir = new Vec3(look.x, 0, look.z).normalize();
        if (target != null) {
            float dy = (float) (projectilePos.y - target.getY());
            float dx = (float) (projectilePos.x - target.getX());
            float dz = (float) (projectilePos.z - target.getZ());
            float dist = (float) Math.sqrt(dx * dx + dz * dz);
            float timeGuess = (float) Math.sqrt(2 * dy / EntityPoisonBall.GRAVITY);
            float speed = Math.min(dist/timeGuess, 0.9f);
            poisonBall.shoot(dir.x * speed, 0.1, dir.z * speed, 1f, 0);
        }
        this.level().addFreshEntity(poisonBall);

        playSound(MMSounds.ENTITY_NAGA_ACID_SPIT.get(), 2, 1);
        playSound(MMSounds.ENTITY_NAGA_ACID_SPIT_HISS.get(), 2, 1);
    }

@Override
    public void tick() {
        super.tick();
        LivingEntity entityTarget = entity.getTarget();
        if (entityTarget != null) {
            entity.lookAt(entityTarget, 100, 100);
            entity.getLookControl().setLookAt(entityTarget, 30F, 30F);
            if (entity.getAnimationTick() == attackFrame) {
                entity.performRangedAttack(entityTarget, 0);
                if (attackSound != null) {
                    entity.playSound(attackSound, 1, 1);
                }
            }
        }
    }

@Override
    public void tick() {
        if (!this.gate.isBound()) {
            this.remove(RemovalReason.DISCARDED);
            return;
        }

        super.tick();

        if (!this.level().isClientSide()) {
            if (!this.unresolvedWaveEntities.isEmpty()) {
                for (UUID id : this.unresolvedWaveEntities) {
                    Entity e = ((ServerLevel) this.level()).getEntity(id);
                    if (e instanceof LivingEntity) this.currentWaveEntities.add((LivingEntity) e);
                }
                this.unresolvedWaveEntities.clear();
            }

            if (this.isWaveActive()) {
                int maxWaveTime = this.getMaxWaveTime();
                if (this.getTicksActive() > maxWaveTime) {
                    this.onFailure(this.currentWaveEntities, FailureReason.TIMER_ELAPSED);
                    return;
                }
            }

            this.entityData.set(TICKS_ACTIVE, this.getTicksActive() + 1);

            // If we don't have a nearby player, tick down the counter, and if it reaches zero, fail the gateway.
            if (!this.entityData.get(HAS_NEARBY_PLAYER)) {
                this.nearbyPlayerTimer--;
                if (this.nearbyPlayerTimer <= 0) {
                    this.onFailure(this.currentWaveEntities, FailureReason.NO_NEARBY_PLAYER);
                    return;
                }
            }
            else {
                this.nearbyPlayerTimer = 200; // Reset the timer if we have a nearby player.
            }

            // Collect all remaining enemies, which are those that are alive and not removed via a valid reason.
            List<LivingEntity> enemies = this.currentWaveEntities.stream().filter(e -> e.getHealth() > 0 && !this.isValidRemoval(e.getRemovalReason())).toList();
            if (this.tickCount % 20 == 0) {
                for (LivingEntity entity : enemies) {
                    if (hasLeftDimension(entity)) {
                        this.onFailure(this.currentWaveEntities, FailureReason.ENTITY_LEFT_DIMENSION);
                        return;
                    }
                    if (entity.getRemovalReason() == RemovalReason.DISCARDED) {
                        this.onFailure(this.currentWaveEntities, FailureReason.ENTITY_DISCARDED);
                        return;
                    }
                    if (entity.tickCount > 30) {
                        this.spawnParticle(entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), ParticlePayload.EffectType.IDLE);
                    }
                    if (this.isOutOfRange(entity)) {
                        if (this.getGateway().rules().failOnOutOfBounds() || !this.respawnEntity(entity)) {
                            this.onFailure(this.currentWaveEntities, FailureReason.ENTITY_TOO_FAR);
                            return;
                        }
                    }

                    if (this.tickCount % 100 == 0 && entity instanceof Mob mob) {
                        if (!(mob.getTarget() instanceof Player)) {
                            Player p = summonerOrClosest();
                            if (!(p instanceof FakePlayer)) {
                                mob.setTarget(p);
                            }
                        }
                    }
                }

                Player player = this.level().getNearestPlayer(this, this.getGateway().getLeashRangeSq());
                this.entityData.set(HAS_NEARBY_PLAYER, player != null);
            }
            this.entityData.set(ENEMIES, enemies.size());

            if (this.tickCount % 4 == 0 && !this.undroppedItems.isEmpty()) {
                for (int i = 0; i < this.getDropCount(); i++) {
                    this.spawnItem(this.undroppedItems.remove());
                    if (this.undroppedItems.isEmpty()) break;
                }
            }

            if (this.isWaveActive()) {
                if (enemies.isEmpty()) {
                    this.completeWave();
                    NeoForge.EVENT_BUS.post(new GateEvent.WaveEnd(this));
                    this.currentWaveEntities.clear();
                    this.entityData.set(WAVE_ACTIVE, false);
                    this.entityData.set(TICKS_ACTIVE, 0);
                    this.entityData.set(WAVE, this.getWave() + 1);
                }
            }
            else {
                if (this.canStartNextWave()) {
                    this.startNextWave();
                    this.entityData.set(WAVE_ACTIVE, true);
                    this.entityData.set(TICKS_ACTIVE, 0);
                    this.entityData.set(ENEMIES, this.currentWaveEntities.size());
                    NeoForge.EVENT_BUS.post(new GateEvent.WaveStarted(this));
                    return;
                }
                else if (this.isCompleted()) {
                    completeGateway();
                }
            }
        }
        else {
            if (this.tickCount % 30 == 0) {
                ParticleHandler.spawnIdleParticles(this);
            }
        }
    }

protected boolean canStartNextWave() {
        return this.getTicksActive() > this.getSetupTime();
    }

protected boolean isValidRemoval(@Nullable RemovalReason reason) {
        GateRules rules = this.getGateway().rules();
        return reason == RemovalReason.KILLED || (rules.allowDiscarding() && reason == RemovalReason.DISCARDED) || (rules.allowDimChange() && reason == RemovalReason.CHANGED_DIMENSION);
    }

protected void startNextWave() {
        List<LivingEntity> spawned = this.getCurrentWave().spawnWave((ServerLevel) this.level(), this.position(), this);
        this.currentWaveEntities.addAll(spawned);
    }

protected void completeGateway() {
        this.remove(RemovalReason.KILLED);
        this.playSound(GatewayObjects.GATE_END.value(), 16, 1);

        AABB completionBB = this.getBoundingBox().inflate(10 + this.getGateway().rules().leashRange());
        this.level().getEntitiesOfClass(Player.class, completionBB).forEach(p -> {
            p.awardStat(GatewayObjects.GATES_DEFEATED);
            if (p instanceof ServerPlayer sp) {
                GatewayObjects.FINISH_GATEWAY.trigger(sp, this.getGateway());
            }
        });
        NeoForge.EVENT_BUS.post(new GateEvent.Completed(this));
    }

public Player summonerOrClosest() {
        if (this.knownPlayer != null) {
            Player player = this.knownPlayer.get();
            if (player != null && player.isAlive()) {
                return player;
            }
            else {
                this.knownPlayer = null;
            }
        }

        Player player = this.level().getPlayerByUUID(this.summonerId);
        if (player == null) {
            player = this.level().getNearestPlayer(this, 50);
        }

        if (player == null) {
            GameProfile profile = new GameProfile(this.summonerId, "Gateway_Summoner");
            return FakePlayerFactory.get((ServerLevel) this.level(), profile);
        }

        this.knownPlayer = new WeakReference<>(player);
        return player;
    }

public void onFailure(Collection<LivingEntity> remaining, FailureReason reason) {
        this.failureReason = reason;
        NeoForge.EVENT_BUS.post(new GateEvent.Failed(this));
        Player player = this.summonerOrClosest();
        if (player != null) player.sendSystemMessage(reason.getMsg());
        spawnLightningOn(this, false);
        remaining.stream().filter(Entity::isAlive).forEach(e -> {
            if (this.getGateway().rules().removeOnFailure()) {
                spawnLightningOn(e, true);
                e.remove(RemovalReason.DISCARDED);
            }
            else if (e instanceof Mob mob) {
                mob.persistenceRequired = false;
            }
        });
        this.getGateway().failures().forEach(f -> f.onFailure((ServerLevel) this.level(), this, player, reason));
        this.remove(RemovalReason.DISCARDED);
    }

public void playerDied(Player player) {
        if (this.getGateway().rules().lives() != -1 && this.distanceToSqr(player) <= Mth.square(this.getGateway().rules().leashRange() + 25)) {
            int lives = this.getRemainingLives() - 1;
            if (lives <= 0) {
                this.onFailure(this.currentWaveEntities, FailureReason.OUT_OF_LIVES);
            }
            else {
                this.setRemainingLives(lives);
            }
        }
    }

@Override
    protected void addAdditionalSaveData(ValueOutput output) {
        output.putInt("wave", this.getWave());
        output.putString("gate", this.gate.getId().toString());
        java.util.List<UUID> waveEntityIds = new java.util.ArrayList<>();
        for (LivingEntity e : this.currentWaveEntities) {
            waveEntityIds.add(e.getUUID());
        }
        output.store("wave_entities", UUIDUtil.CODEC.listOf(), waveEntityIds);
        output.putBoolean("active", this.isWaveActive());
        output.putInt("ticks_active", this.getTicksActive());
        output.store("summoner", UUIDUtil.CODEC, this.summonerId);
        output.store("queued_stacks", ItemStack.CODEC.listOf(), new java.util.ArrayList<>(this.undroppedItems));
        output.putInt("lives", this.getRemainingLives());
        output.putInt("nearby_player_timer", this.nearbyPlayerTimer);
    }

@Override
    protected void readAdditionalSaveData(ValueInput input) {
        this.entityData.set(WAVE, input.getIntOr("wave", 0));
        input.getString("gate").ifPresent(gateId -> this.gate = GatewayRegistry.INSTANCE.holder(Identifier.tryParse(gateId)));

        if (!this.gate.isBound()) {
            Gateways.LOGGER.error("Invalid gateway at {} will be removed.", this.position());
            this.remove(RemovalReason.DISCARDED);
            return;
        }

        input.read("wave_entities", UUIDUtil.CODEC.listOf()).ifPresent(uuids -> {
            this.currentWaveEntities.clear();
            this.unresolvedWaveEntities.clear();
            this.unresolvedWaveEntities.addAll(uuids);
        });

        this.entityData.set(WAVE_ACTIVE, input.getBooleanOr("active", false));
        this.entityData.set(TICKS_ACTIVE, input.getIntOr("ticks_active", 0));
        input.read("summoner", UUIDUtil.CODEC).ifPresent(id -> this.summonerId = id);
        input.read("queued_stacks", ItemStack.CODEC.listOf()).ifPresent(stacks -> {
            this.undroppedItems.clear();
            stacks.stream().filter(s -> !s.isEmpty()).forEach(this.undroppedItems::add);
        });
        this.setRemainingLives(input.getIntOr("lives", -1));
        this.nearbyPlayerTimer = input.getIntOr("nearby_player_timer", 0);

        this.bossEvent = this.createBossEvent();
        this.refreshDimensions();
    }

public void spawnItem(ItemStack stack) {
        ItemEntity i = new ItemEntity(this.level(), 0, 0, 0, stack);
        i.setPos(this.getX() + Mth.nextDouble(this.random, -0.5, 0.5), this.getY() + 1.5, this.getZ() + Mth.nextDouble(this.random, -0.5, 0.5));
        i.setDeltaMovement(Mth.nextDouble(this.random, -0.15, 0.15), 0.4, Mth.nextDouble(this.random, -0.15, 0.15));
        this.level().addFreshEntity(i);
        this.level().playSound(null, i.getX(), i.getY(), i.getZ(), GatewayObjects.GATE_WARP, SoundSource.HOSTILE, 0.25F, 2.0F);
    }

public void handleConversion(Entity entity, LivingEntity outcome) {
        entity.getPersistentData().remove("gateways.owner");
        outcome.getPersistentData().store("gateways.owner", UUIDUtil.CODEC, this.getUUID());

        if (this.unresolvedWaveEntities.contains(entity.getUUID())) {
            this.unresolvedWaveEntities.remove(entity.getUUID());
            this.unresolvedWaveEntities.add(outcome.getUUID());
        }
        else if (this.currentWaveEntities.contains(entity)) {
            this.currentWaveEntities.remove(entity);
            this.currentWaveEntities.add(outcome);
        }
    }

public boolean respawnEntity(Entity entity) {
        SpawnAlgorithm algo = this.getGateway().spawnAlgo();
        Vec3 pos = algo.spawn((ServerLevel) this.level(), this.position(), this, entity);
        if (pos == null) return false;
        entity.resetFallDistance();
        this.spawnParticle(entity.getX(), entity.getY(), entity.getZ(), ParticlePayload.EffectType.SPAWNED);
        entity.setPos(pos);
        this.spawnParticle(entity.getX(), entity.getY(), entity.getZ(), ParticlePayload.EffectType.SPAWNED);
        if (entity instanceof Mob mob) {
            Player p = summonerOrClosest();
            if (!(p instanceof FakePlayer)) mob.setTarget(p);
        }
        return true;
    }

public static boolean hasLeftDimension(Entity entity) {
        return entity.getRemovalReason() == RemovalReason.CHANGED_DIMENSION;
    }

@Nullable
    public static GatewayEntity getOwner(Entity entity) {
        return entity.getPersistentData().read("gateways.owner", UUIDUtil.CODEC).map(id -> {
            if (entity.level() instanceof ServerLevel sl && sl.getEntity(id) instanceof GatewayEntity gate && gate.isValid()) {
                return gate;
            }
            return null;
        }).orElse(null);
    }

public boolean isLastWave() {
        return this.getWave() >= this.getGateway().getNumWaves();
    }

@Override
    public Wave getCurrentWave() {
        return this.getGateway().getWave(Math.min(this.getGateway().getNumWaves() - 1, this.getWave()));
    }

@Override
    protected boolean canStartNextWave() {
        return super.canStartNextWave() && !this.isLastWave();
    }

@Override
    public boolean isCompleted() {
        return this.undroppedItems.isEmpty() && this.isLastWave();
    }

@Override
    protected void completeWave() {
        Player player = this.summonerOrClosest();
        this.undroppedItems.addAll(this.getCurrentWave().spawnRewards((ServerLevel) this.level(), this, player));
    }

@Override
    protected void completeGateway() {
        super.completeGateway();
        Player player = this.summonerOrClosest();
        this.getGateway().rewards().forEach(r -> {
            r.generateLoot((ServerLevel) this.level(), this, player, this::spawnCompletionItem);
        });
    }

@Override
    public void tick() {
        super.tick();
        if (this.isRemoved()) return;
        if (this.getMaxEnemies() == -1) {
            this.computeMaxEnemies(this.getWave());
        }
    }

@Override
    protected void startNextWave() {
        super.startNextWave();
        this.entityData.set(MAX_WAVE_TIME, this.getCurrentWave().maxWaveTime());
        this.entityData.set(SETUP_TIME, this.getCurrentWave().setupTime());

        // First pass, spawn additional wave entities.
        executeModifiers(m -> m.entities().forEach(waveEntity -> {
            for (int i = 0; i < waveEntity.getCount(); i++) {
                LivingEntity entity = Wave.spawnWaveEntity((ServerLevel) this.level(), this.position(), this, getCurrentWave(), waveEntity);
                if (entity == null) {
                    this.onFailure(this.currentWaveEntities, FailureReason.SPAWN_FAILED);
                    break;
                }
                else this.currentWaveEntities.add(entity);
            }
        }));

        // Second pass, apply wave modifiers to all entities.
        int applied = executeModifiers(m -> {
            for (LivingEntity entity : this.currentWaveEntities) {
                for (WaveModifier waveModif : m.modifiers()) {
                    waveModif.apply(entity, this);
                }
                entity.setHealth(entity.getMaxHealth());
            }

            if (m.waveTime() != 0) {
                this.entityData.set(MAX_WAVE_TIME, this.getMaxWaveTime() + m.waveTime());
            }

            if (m.setupTime() != 0) {
                this.entityData.set(SETUP_TIME, Math.max(0, this.getSetupTime() + m.setupTime()));
            }
        });

        this.entityData.set(MODIFIERS, applied);
        this.entityData.set(MAX_ENEMIES, this.currentWaveEntities.size());
    }

@Override
    protected void completeWave() {
        Player player = this.summonerOrClosest();
        this.undroppedItems.addAll(this.getCurrentWave().spawnRewards((ServerLevel) this.level(), this, player));
        executeModifiers(m -> m.rewards().forEach(r -> r.generateLoot((ServerLevel) this.level(), this, player, this.undroppedItems::add)));
        this.computeMaxEnemies(this.getWave() + 1); // Precompute max enemies for the next wave so it can be displayed.
    }

@Override
    protected void addAdditionalSaveData(ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putInt("max_enemies", this.getMaxEnemies());
        output.putInt("modifiers_applied", this.getModifiersApplied());
    }

@Override
    protected void readAdditionalSaveData(ValueInput input) {
        super.readAdditionalSaveData(input);
        this.entityData.set(MAX_ENEMIES, input.getIntOr("max_enemies", -1));
        this.entityData.set(MODIFIERS, input.getIntOr("modifiers_applied", -1));
        this.entityData.set(MAX_WAVE_TIME, this.getCurrentWave().maxWaveTime());
        this.entityData.set(SETUP_TIME, this.getCurrentWave().setupTime());
    }

public List<LivingEntity> spawnWave(ServerLevel level, Vec3 pos, GatewayEntity gate) {
        List<LivingEntity> spawned = new ArrayList<>();
        for (WaveEntity toSpawn : this.entities) {
            for (int i = 0; i < toSpawn.getCount(); i++) {
                LivingEntity entity = spawnWaveEntity(level, pos, gate, this, toSpawn);
                if (entity == null) {
                    gate.onFailure(spawned, FailureReason.SPAWN_FAILED);
                    break;
                }
                spawned.add(entity);
            }
        }

        return spawned;
    }

@Nullable
    public static LivingEntity spawnWaveEntity(ServerLevel level, Vec3 pos, GatewayEntity gate, Wave wave, WaveEntity waveEntity) {
        LivingEntity entity = waveEntity.createEntity(level, gate);
        if (entity == null) {
            Gateways.logSpawnDebug(gate, waveEntity, "Entity creation returned null");
            return null;
        }

        Vec3 spawnPos = gate.getGateway().spawnAlgo().spawn(level, pos, gate, entity);
        if (spawnPos == null) {
            Gateways.logSpawnDebug(gate, waveEntity, "Spawn algorithm returned null position");
            return null;
        }

        entity.getPersistentData().store("gateways.owner", UUIDUtil.CODEC, gate.getUUID());
        entity.snapTo(spawnPos.x(), spawnPos.y(), spawnPos.z(), level.getRandom().nextFloat() * 360, level.getRandom().nextFloat() * 360);

        entity.getPassengersAndSelf().filter(e -> e instanceof LivingEntity).map(LivingEntity.class::cast).forEach(e -> {
            wave.modifiers.forEach(m -> m.apply(e, gate));
            e.setHealth(e.getMaxHealth());
            e.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, 5, 100, true, false));
        });

        GateRules rules = gate.getGateway().rules();

        if (entity instanceof Mob mob) {
            if (waveEntity.shouldFinalizeSpawn()) {
                EventHooks.finalizeMobSpawn(mob, level, level.getCurrentDifficultyAt(entity.blockPosition()), EntitySpawnReason.SPAWNER, null);
            }
            Player summoner = gate.summonerOrClosest();
            if (!(summoner instanceof FakePlayer)) {
                mob.setTarget(summoner);
            }
            mob.setPersistenceRequired();

            // Override the drop chances to the rules-specified default if they are unchanged from the default of 0.085F
            if (rules.defaultDropChance() >= 0) {
                for (EquipmentSlot slot : EquipmentSlot.values()) {
                    if (mob.getDropChances().byEquipment(slot) == DropChances.DEFAULT_EQUIPMENT_DROP_CHANCE) {
                        mob.setDropChance(slot, rules.defaultDropChance());
                    }
                }
            }
        }

        if (rules.followRangeBoost() > 0) {
            AttributeInstance attr = entity.getAttribute(Attributes.FOLLOW_RANGE);
            if (attr != null) {
                attr.addPermanentModifier(new AttributeModifier(Gateways.loc("follow_range_boost"), rules.followRangeBoost(), Operation.ADD_VALUE));
            }
        }

        NeoForge.EVENT_BUS.post(new GateEvent.WaveEntitySpawned(gate, entity));
        level.addFreshEntityWithPassengers(entity);
        level.playSound(null, gate.getX(), gate.getY(), gate.getZ(), GatewayObjects.GATE_WARP, SoundSource.HOSTILE, 0.5F, 1);
        gate.spawnParticle(entity.getX(), entity.getY(), entity.getZ(), ParticlePayload.EffectType.SPAWNED);
        return entity;
    }

public List<ItemStack> spawnRewards(ServerLevel level, GatewayEntity gate, Player summoner) {
        List<ItemStack> stacks = new ArrayList<>();
        this.rewards.forEach(r -> r.generateLoot(level, gate, summoner, s -> {
            if (!s.isEmpty()) {
                while (s.getCount() > 4) {
                    ItemStack copy = s.copy();
                    copy.setCount(4);
                    stacks.add(copy);
                    s.shrink(4);
                }
                if (!s.isEmpty()) stacks.add(s);
            }
        }));
        return stacks;
    }
